{
  "aggregate": {{ this.params.collection }},
  "pipeline": {{
    (() => {
			const targetDomains = this.params.domain || [];

      const limitCount = Number(this.params.questionLimit) || 10;
      const onlyWrong = this.params.onlyWrong === true || this.params.onlyWrong === "true";
      const excludeIds = this.params.excludeIds || [];
      const targetOrigins = this.params.origins || [];
      const errorGroup = this.params.errorGroup;
      const errorReverseOrder = this.params.errorReverseOrder === true || 		this.params.errorReverseOrder === "true";

      let matchConditions = {};

      // 1. Filter nach mehreren Domains
			if (targetDomains.length > 0) {
					matchConditions["domain"] = {
							"$in": targetDomains
					};
			}

      // 2. Filter nach Fehlergruppe oder countWrong > 0
      if (
        errorGroup !== undefined &&
        errorGroup !== null &&
        errorGroup !== ""
      ) {
        matchConditions["countWrong"] = Number(errorGroup);
      } else if (onlyWrong) {
        matchConditions["countWrong"] = {
          "$exists": true,
          "$gt": 0
        };
      }

      // 3. Bereits geladene Fragen ausschließen
      if (Array.isArray(excludeIds) && excludeIds.length > 0) {
        matchConditions["_id"] = {
          "$nin": excludeIds
        };
      }

      // 4. Filtern nach mehreren Origin-Werten
      if (Array.isArray(targetOrigins) && targetOrigins.length > 0) {
        matchConditions["origin"] = {
          "$in": targetOrigins
        };
      }

      let pipeline = [
        {
          "$match": matchConditions
        }
      ];

      // 5. Sortierung oder zufällige Auswahl
      if (errorReverseOrder) {
        pipeline.push(
          { "$sort": { "countWrong": -1 } },
          { "$limit": limitCount }
        );
      } else {
        pipeline.push(
          { "$sample": { "size": limitCount } }
        );
      }

      // 6. Lookup für Antworten
      pipeline.push(
        {
          "$lookup": {
            "from": "master_answer",
            "localField": "_id",
            "foreignField": "question_id",
            "as": "answers"
          }
        }
      );

      return pipeline;
    })()
  }},
  "cursor": {
    "batchSize": {{ Math.max(1, Number(this.params.questionLimit) || 10) }}
  }
}
